import datetime
from dateutil import tz

def normalize_timestamp(value):
    try:
        naive_datetime = datetime.datetime.fromisoformat(value)
        if naive_datetime.tzinfo is None:
            raise ValueError("Naive timestamps must include a timezone.")
        aware_utc_datetime = naive_datetime.astimezone(tz=datetime.timezone.utc).replace(microsecond=0)
        return aware_utc_datetime
    except ValueError as e:
        raise ValueError("Invalid timestamp format.") from e

